// lz-compress: greedy LZ77 over a generated byte buffer (see lz-compress.mi).

function generatedInput(n: number): Uint8Array {
  const data = new Uint8Array(n);
  let len = 0;
  let state = 11;
  while (len < n) {
    state = (state * 48271) % 2147483647;
    if (len > 64 && state % 4 === 0) {
      const back = 1 + (Math.floor(state / 4) % 60);
      const length = 3 + (Math.floor(state / 256) % 20);
      for (let k = 0; k < length && len < n; k++) {
        data[len] = data[len - back];
        len++;
      }
    } else {
      data[len++] = 97 + (state % 16);
    }
  }
  return data;
}

function kernel(n: number): string {
  const data = generatedInput(n);
  const size = data.length;
  let literals = 0;
  let matches = 0;
  let hash = 0;
  let pos = 0;
  while (pos < size) {
    let bestLength = 0;
    let bestDistance = 0;
    for (let start = Math.max(0, pos - 255); start < pos; start++) {
      let length = 0;
      while (pos + length < size && length < 255 && data[start + length] === data[pos + length]) {
        length++;
      }
      if (length > bestLength) {
        bestLength = length;
        bestDistance = pos - start;
      }
    }
    if (bestLength >= 3) {
      matches += 1;
      hash = (hash * 31 + bestDistance * 256 + bestLength) % 1000000007;
      pos += bestLength;
    } else {
      literals += 1;
      hash = (hash * 31 + data[pos]) % 1000000007;
      pos += 1;
    }
  }
  return `${literals} ${matches} ${hash}`;
}

function nowNs(): bigint {
  return BigInt(Math.round(performance.now() * 1e6));
}

function runHot(input: number): string {
  const expected = kernel(input);
  let agree = true;
  for (let i = 1; i < 5; i++) {
    const checksum = kernel(input);
    agree = agree && checksum === expected;
  }
  for (let i = 0; i < 5; i++) {
    const start = nowNs();
    const checksum = kernel(input);
    const elapsed = nowNs() - start;
    console.error(`hot_ns=${elapsed}`);
    agree = agree && checksum === expected;
  }
  if (!agree) {
    console.error("checksum differs between iterations");
    Deno.exit(1);
  }
  return expected;
}

const input = parseInt(Deno.readTextFileSync(Deno.args[0]).trim(), 10);
console.log(Deno.args[1] === "hot" ? runHot(input) : kernel(input));
